"""Baseline: measured outline extruded, holes cut. Generated by baseline_cad.py."""
import cadquery as cq


def build_part(
    thickness=3.0,
    corner1_u=-34.67, corner1_v=-20.16,
    corner2_u=-34.65, corner2_v=20.1,
    corner3_u=34.68, corner3_v=20.1,
    corner4_u=34.12, corner4_v=-20.06,
    hole1_u=-14.9, hole1_v=-0.1, hole1_length=16.0, hole1_width=8.23, hole1_angle=0.0,
    hole2_u=14.75, hole2_v=-0.11, hole2_length=19.84, hole2_width=6.22, hole2_angle=0.0,
):
    part = cq.Workplane("XY").polyline([(corner1_u, corner1_v), (corner2_u, corner2_v), (corner3_u, corner3_v), (corner4_u, corner4_v)]).close().extrude(thickness)
    part = part.cut(cq.Workplane("XY", origin=(hole1_u, hole1_v, -1)).transformed(rotate=(0, 0, hole1_angle)).rect(hole1_length, hole1_width).extrude(thickness + 2))
    part = part.cut(cq.Workplane("XY", origin=(hole2_u, hole2_v, -1)).transformed(rotate=(0, 0, hole2_angle)).slot2D(hole2_length, hole2_width).extrude(thickness + 2))
    return part
